<div class="grid cols3" style="gap:12px"><label class="sl-field"><span class="sl-lab">Service</span><span class="sl-sel native"><select name="ship_mode" id="re-mode"><?php foreach ($d['modes'] as $id => $n): ?><option value="<?= (int) $id ?>" <?= $sel($id, $v['mode']) ?>><?= h($n) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field"><span class="sl-lab">From</span><span class="sl-sel native"><select name="country_origin"><option value="">Origin country</option><?php foreach ($d['countries'] as $c): ?><option value="<?= (int) $c->id ?>" <?= $sel($c->id, $v['origin']) ?>><?= h($c->name) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field"><span class="sl-lab">To</span><span class="sl-sel native"><select name="country_destiny" data-reload="destiny"><option value="">Destination country</option><?php foreach ($d['countries'] as $c): ?><option value="<?= (int) $c->id ?>" <?= $sel($c->id, $v['destiny']) ?>><?= h($c->name) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label></div>
<div class="grid cols3" style="gap:12px"><label class="sl-field"><span class="sl-lab">State / region</span><span class="sl-sel native"><select name="state_destinystates" data-reload="state"><option value="">Pick a state</option><?php foreach ($d['states'] as $c): ?><option value="<?= (int) $c->id ?>" <?= $sel($c->id, $v['state']) ?>><?= h($c->name) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field"><span class="sl-lab">City</span><span class="sl-sel native"><select name="city_destinycities"><option value="">Pick a city</option><?php foreach ($d['cities'] as $c): ?><option value="<?= (int) $c->id ?>" <?= $sel($c->id, $v['city']) ?>><?= h($c->name) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label>
<label class="sl-field"><span class="sl-lab">Customer (optional)</span><span class="sl-sel native"><select name="client_id"><option value="">Everyone</option><?php foreach ($d['clients'] as $c): ?><option value="<?= (int) $c->id ?>" <?= $sel($c->id, $v['client']) ?>><?= h(trim($c->fname . ' ' . $c->lname) . ($c->locker ? ' · ' . $c->locker : '')) ?></option><?php endforeach; ?></select><i class="ic ic-sm i-down" aria-hidden="true"></i></span></label></div>
<div class="grid cols3" style="gap:12px"><label class="sl-field"><span class="sl-lab">Band from (<span class="re-unit">lb</span>)</span><input class="sl-in mono" name="initial_range" value="<?= h($v['from']) ?>" inputmode="decimal" required></label><label class="sl-field"><span class="sl-lab">Band to (<span class="re-unit">lb</span>)</span><input class="sl-in mono" name="final_range" value="<?= h($v['to']) ?>" inputmode="decimal" required></label><label class="sl-field"><span class="sl-lab">Price per <span class="re-unit">lb</span></span><input class="sl-in mono" name="tariff_price" id="re-price" value="<?= h($v['price']) ?>" inputmode="decimal" required></label></div>
<div class="grid cols3" style="gap:12px"><label class="sl-field"><span class="sl-lab">Minimum charge</span><input class="sl-in mono" name="min_charge" id="re-min" value="<?= h($v['min']) ?>" inputmode="decimal"<?= $d['hasMin'] ? '' : ' disabled title="Run the finance upgrade to enable"' ?>></label><label class="sl-field"><span class="sl-lab">Volume divisor</span><input class="sl-in mono" name="volumetric_percentage" value="<?= h($v['vol']) ?>" inputmode="numeric" required></label><label class="sl-field"><span class="sl-lab">Price per mile</span><input class="sl-in mono" name="price_mile" value="<?= h($v['mile']) ?>" inputmode="decimal"></label></div>
<div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Valid from</span><input class="sl-in mono" type="date" name="valid_from" value="<?= h($v['vfrom']) ?>"<?= $d['hasMin'] ? '' : ' disabled' ?>></label><label class="sl-field"><span class="sl-lab">Valid until</span><input class="sl-in mono" type="date" name="valid_until" value="<?= h($v['vto']) ?>"<?= $d['hasMin'] ? '' : ' disabled' ?>></label></div></section>
<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Fees</h2></div><div class="sl-kv"><div><span>Insurance</span><span><?= h($d['insurance']) ?>% of declared value</span></div><div><span>Customs tariff</span><span><?= h($core->tax_custom_tariffis ?? 0) ?>%</span></div><div><span>Handling (GHS)</span><span>tiered, added at billing</span></div></div><a class="sl-btn ghost sm" style="align-self:flex-start" href="tools.php"><i class="ic ic-sm i-cog" aria-hidden="true"></i>Edit fees in Settings</a></section></div>
<aside class="b col g16"><section class="sl-card col g16"><div class="sl-ch" style="margin:0"><h2 class="sl-ct">Try it</h2></div><div class="grid cols2" style="gap:12px"><label class="sl-field"><span class="sl-lab">Weight (<span class="re-unit">lb</span>)</span><input class="sl-in mono" id="re-w" value="5.6" inputmode="decimal"></label><label class="sl-field"><span class="sl-lab">Declared value</span><input class="sl-in mono" id="re-dv" value="100" inputmode="decimal"></label></div><div class="sl-kv" id="re-out"></div></section></aside></div>
</form>
<script>
(function(){var f=document.getElementById('re-form'),sym=<?= json_encode($core->for_symbol ?? '$') ?>,ins=<?= json_encode((float) $d['insurance']) ?>;function m(n){return sym+n.toFixed(2);}
function unit(){var u=document.getElementById('re-mode').value==='27'?'cu ft':'lb';f.querySelectorAll('.re-unit').forEach(function(x){x.textContent=u;});return u;}
function calc(){var u=unit(),w=parseFloat(document.getElementById('re-w').value)||0,p=parseFloat(document.getElementById('re-price').value)||0,mn=parseFloat(document.getElementById('re-min').value)||0,dv=parseFloat(document.getElementById('re-dv').value)||0,fr=Math.max(w*p,mn),i=dv*ins/100;
document.getElementById('re-out').innerHTML='<div><span>Freight '+w+' '+u+' × '+m(p)+'</span><span>'+m(fr)+'</span></div><div><span>Insurance</span><span>'+m(i)+'</span></div><div><span>Total</span><span>'+m(fr+i)+'</span></div>';}
f.addEventListener('input',calc);f.addEventListener('change',function(e){var k=e.target.getAttribute('data-reload');if(!k)return;var u=new URL(location.href);u.searchParams.set(k,e.target.value);if(k==='destiny')u.searchParams.delete('state');u.searchParams.set('mode',document.getElementById('re-mode').value);u.searchParams.set('origin',f.country_origin.value);location.href=u;});calc();})();
</script>
